// Partner Center Customer Retrieval
// Fetches customer details from Microsoft Partner Center API

var customerId = input.get("customerId");
var accessToken = input.get("accessToken");

if (!customerId || customerId.trim() === "") {
    log.error("Customer ID is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Customer ID is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else if (!accessToken || accessToken.trim() === "") {
    log.error("Access Token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access Token is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else {
    try {
        var url = "https://api.partnercenter.microsoft.com/v1/customers/" + customerId.trim();

        log.info("Fetching customer: " + customerId);

        var response = http.get(url, {
            "Authorization": "Bearer " + accessToken.trim()
        });

        output.set("StatusCode", response.statusCode);
        output.set("Body", response.body);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            var customer = json.parse(response.body);

            // Core identifiers
            output.set("CustomerId", customer.id || "");
            output.set("CommerceId", customer.commerceId || "");
            output.set("RelationshipToPartner", customer.relationshipToPartner || "");

            // Company profile
            var company = customer.companyProfile || {};
            output.set("CompanyName", company.companyName || "");
            output.set("Domain", company.domain || "");
            output.set("TenantId", company.tenantId || "");
            output.set("CompanyEmail", company.email || "");

            // Company address
            var companyAddr = company.address || {};
            output.set("CompanyCountry", companyAddr.country || "");
            output.set("CompanyCity", companyAddr.city || "");
            output.set("CompanyState", companyAddr.state || "");
            output.set("CompanyPostalCode", companyAddr.postalCode || "");
            output.set("CompanyAddressLine1", companyAddr.addressLine1 || "");
            output.set("CompanyPhone", companyAddr.phoneNumber || "");

            // Billing profile
            var billing = customer.billingProfile || {};
            output.set("BillingId", billing.id || "");
            output.set("BillingEmail", billing.email || "");
            output.set("BillingCulture", billing.culture || "");
            output.set("BillingLanguage", billing.language || "");

            // Billing contact
            var billingAddr = billing.defaultAddress || {};
            output.set("BillingFirstName", billingAddr.firstName || "");
            output.set("BillingLastName", billingAddr.lastName || "");
            output.set("BillingPhone", billingAddr.phoneNumber || "");

            // Custom domains as JSON array
            var domains = customer.customDomains || [];
            output.set("CustomDomains", json.stringify(domains));
            output.set("CustomDomainsCount", domains.length);

            // Tags
            var tags_data = customer.tags || [];
            output.set("Tags", json.stringify(tags_data));

            output.set("HasErrors", false);
            output.set("ErrorMessage", "");

            log.info("Successfully retrieved customer: " + (company.companyName || customerId));
            tags.trigger("success");
        } else {
            var errorMsg = "API returned status " + response.statusCode;
            try {
                var errorBody = json.parse(response.body);
                if (errorBody.message) errorMsg = errorBody.message;
                else if (errorBody.error_description) errorMsg = errorBody.error_description;
            } catch (e) {
                if (response.body) errorMsg = response.body.substring(0, 500);
            }

            log.error("Failed to retrieve customer: " + errorMsg);
            output.set("HasErrors", true);
            output.set("ErrorMessage", errorMsg);
            tags.trigger("error");
        }
    } catch (ex) {
        log.error("Request failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Request failed: " + ex.message);
        output.set("StatusCode", 0);
        tags.trigger("error");
    }
}
